INSERT INTO public.vehicles (id, slug, name, display_name, class, manufacturer, top_speed, acceleration, handling, weight, summary, images, status, verification, confidence, source, price, price_display, seating, drivetrain, power_hp) VALUES
  ('visione', 'grotti-visione', 'Grotti Visione', 'Grotti Visione', 'Super', 'Grotti', 220 || ' mph', '2.8s', 92 || '/100', '1,380 kg', 'The pinnacle of Italian hypercar engineering. Blistering straight-line acceleration and race-honed aerodynamics make it unmatched on open highways.', ARRAY['/img/car-purple.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'Rockstar Trailer 1 & Reveal Key Art', 2850000, '$2,850,000', 2, 'RWD', 1250),
  ('tulip', 'declasse-tulip', 'Declasse Tulip', 'Declasse Tulip', 'Muscle', 'Declasse', 175 || ' mph', '4.4s', 74 || '/100', '1,720 kg', 'Classic American big-block muscle with intoxicating engine roar and high tail-out drifting control. Perfect getaway cruiser for four passengers.', ARRAY['/img/car-orange.jpg']::TEXT[], 'published', 'verified', 'OFFICIAL', 'Rockstar Games Trailer 1 (0:42 mark)', 185000, '$185,000', 4, 'RWD', 650),
  ('banshee-gts', 'bravado-banshee-gts', 'Bravado Banshee GTS', 'Bravado Banshee GTS', 'Sports', 'Bravado', 195 || ' mph', '3.3s', 85 || '/100', '1,450 kg', 'The timeless American sports icon reborn for Leonida with a high-revving V10 engine, sculpted fenders, and surgical steering response.', ARRAY['/img/car-pink.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'In-Game Leak Assets & Promo Shots', 1250000, '$1,250,000', 2, 'RWD', 750),
  ('reever', 'western-reever', 'Western Reever', 'Western Reever', 'Off-Road', 'Western Company', 140 || ' mph', '5.6s', 76 || '/100', '2,400 kg', 'Heavy-duty 4x4 pickup truck engineered to dominate deep Everglades mud, sandbars, and rocky mountain logging trails without breaking a sweat.', ARRAY['/img/car-pickup.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'Rockstar Trailer 1 Swampland Scenes', 110000, '$110,000', 4, 'AWD', 450),
  ('shotaro', 'nagasaki-shotaro', 'Nagasaki Shotaro', 'Nagasaki Shotaro', 'Motorcycle', 'Nagasaki', 200 || ' mph', '2.6s', 94 || '/100', '240 kg', 'Futuristic neon superbike with supernatural cornering grip and immediate electric-assist launch. Rules the night-time Vice City expressways.', ARRAY['/img/moto-red.jpg']::TEXT[], 'published', 'pending', 'REPORTED', 'Verified Code String References', 1650000, '$1,650,000', 1, 'RWD', 210),
  ('sanchez', 'maibatsu-sanchez', 'Maibatsu Sanchez', 'Maibatsu Sanchez', 'Motorcycle', 'Maibatsu', 115 || ' mph', '4.8s', 88 || '/100', '120 kg', 'The indestructible dirt bike of choice for stunt jumps, back-alley escapes, and off-grid wilderness navigation across rugged Leonida terrain.', ARRAY['/img/moto-red.jpg']::TEXT[], 'published', 'verified', 'OFFICIAL', 'Trailer 1 Dirt Track Scene', 12000, '$12,000', 2, 'RWD', 95),
  ('vortex', 'speeder-vortex', 'Speeder Vortex', 'Speeder Vortex', 'Boat', 'Speeder Marine', 125 || ' mph', '3.9s', 82 || '/100', '2,100 kg', 'High-speed offshore interceptor powerboat designed to evade Coastguard cutters across open Atlantic chop and navigate narrow coastal mangrove channels.', ARRAY['/img/boat.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'Trailer 1 Keys Waterways', 680000, '$680,000', 4, 'AWD', 850),
  ('maverick', 'buckingham-maverick', 'Buckingham Maverick', 'Buckingham Maverick', 'Helicopter', 'Buckingham', 160 || ' mph', '5.2s', 78 || '/100', '1,900 kg', 'The universal twin-engine utility helicopter of Leonida. Reliable passenger transport, rapid heist getaway extraction, and unmatched aerial surveillance.', ARRAY['/img/heli.jpg']::TEXT[], 'published', 'verified', 'OFFICIAL', 'Rockstar Trailer 1 Aerial Pan', 1550000, '$1,550,000', 4, 'AWD', 1100),
  ('comet-s2', 'pfister-comet-s2', 'Pfister Comet S2', 'Pfister Comet S2', 'Sports', 'Pfister', 198 || ' mph', '3.2s', 89 || '/100', '1,410 kg', 'Precision German engineering with rear-engine balance and surgical AWD traction. Carves corners along Biscayne Bay with effortless grace.', ARRAY['/img/car-pink.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'Vice City Beachfront Scene Trailer 1', 1850000, '$1,850,000', 2, 'AWD', 780),
  ('gauntlet-hellfire', 'bravado-gauntlet-hellfire', 'Bravado Gauntlet Hellfire', 'Bravado Gauntlet Hellfire', 'Muscle', 'Bravado', 182 || ' mph', '3.6s', 72 || '/100', '1,880 kg', 'Supercharged Hellcat engine producing tire-shredding torque. Dominates straight-line highway pulls and quarter-mile drag races.', ARRAY['/img/car-orange.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'Trailer 1 Highway Pull Sequence', 745000, '$745,000', 2, 'RWD', 840),
  ('cheetah-classic', 'grotti-cheetah-classic', 'Grotti Cheetah Classic', 'Grotti Cheetah Classic', 'Super', 'Grotti', 190 || ' mph', '3.8s', 83 || '/100', '1,290 kg', 'The definitive 1980s Miami icon. Glistening side strakes, pop-up lights, and intoxicating high-RPM exhaust notes scream retro Vice City royalty.', ARRAY['/img/car-orange.jpg']::TEXT[], 'published', 'pending', 'REPORTED', 'Rockstar Historical Roster Leaks', 1950000, '$1,950,000', 2, 'RWD', 600),
  ('seaplane-dodo', 'mammoth-dodo-seaplane', 'Mammoth Dodo Seaplane', 'Mammoth Dodo Seaplane', 'Plane', 'Mammoth', 135 || ' mph', '6.0s', 70 || '/100', '1,600 kg', 'Versatile twin-float amphibious plane capable of touching down on calm lagoon waters, coastal bays, or remote rural dirt strips.', ARRAY['/img/heli.jpg']::TEXT[], 'published', 'verified', 'CONFIRMED', 'Trailer 1 Coastal Waters', 520000, '$520,000', 4, 'AWD', 700)
