INSERT INTO public.locations (id, slug, name, district, type, verification, coordinates, description, hours, threat_level, img, confidence, source) VALUES
  ('loc-ocean-drive', 'ocean-drive-waterfront', 'Ocean Drive & South Beach Waterfront', 'Ocean Drive', 'Point of Interest', 'verified', 'top 56%, left 64%', 'The world-famous neon art-deco strip. Lined with pastel hotels, bustling outdoor cafes, supercar valets, and sun-soaked coastal beaches.', 'Open 24/7 (Nightlife peaks 22:00 - 05:00)', 'Medium', '/img/hero-dark.jpg', 'OFFICIAL', 'Rockstar Trailer 1 Main Showcase'),
  ('loc-downtown-ammu', 'ammu-nation-downtown', 'Ammu-Nation Flagship — Downtown', 'Vice City Downtown', 'Shop', 'verified', 'top 46%, left 58%', 'Premier military-grade firearms retailer with indoor underground shooting range, heavy armor racks, and high-caliber ammo restocking.', '08:00 – 23:00', 'Low', '/img/gunstore.svg', 'OFFICIAL', 'Trailer 1 Ammu-Nation Exterior Banner'),
  ('loc-malibu-club', 'the-malibu-nightclub', 'The Malibú Neon Nightclub', 'Ocean Drive Waterfront', 'Business', 'verified', 'top 58%, left 62%', 'Legendary multi-level 80s-inspired oceanfront nightclub. High-profile syndicate contacts, VIP bottle service, and massive weekly passive revenue.', '21:00 – 06:00', 'Medium', '/img/vice-sunset.svg', 'CONFIRMED', 'Trailer 1 Club Interior Shots'),
  ('loc-port-gellhorn', 'port-gellhorn-docks', 'Port Gellhorn Cargo Depots & Railyards', 'Port Gellhorn', 'Point of Interest', 'verified', 'top 42%, left 35%', 'Sprawling industrial shipping hub on the western coast. Massive container yards, freight cranes, underground chop shops, and contraband shipping routes.', 'Open 24/7 (Heavy freight traffic)', 'High', '/img/smg-gun.jpg', 'OFFICIAL', 'Trailer 1 Port Gellhorn Road Signs'),
  ('loc-keys-marina', 'leonida-keys-smuggler-marina', 'Leonida Keys Smuggler Marina', 'Leonida Keys', 'Garage', 'verified', 'top 72%, left 45%', 'Archipelago boat slips, fueling docks, and speed boat tuning workshops catering to deep-sea anglers and coastal contraband runners.', 'Open 24/7', 'Medium', '/img/boat.jpg', 'CONFIRMED', 'Trailer 1 Keys Bridge & Waterways'),
  ('loc-grassrivers-marsh', 'grassrivers-everglades-sanctuary', 'Grassrivers Swamplands & Airboat Outpost', 'Grassrivers', 'Point of Interest', 'verified', 'top 35%, left 55%', 'Endless wilderness wetlands inhabited by dangerous wildlife, airboat rental shacks, abandoned cold-war radio beacons, and hidden bootlegger stills.', 'Open 24/7 (High danger after dark)', 'High', '/img/car-pickup.jpg', 'OFFICIAL', 'Rockstar Trailer 1 Swampland Airboat Pan'),
  ('loc-starfish-mansion', 'starfish-island-estates', 'Starfish Island Luxury Enclave', 'Starfish Island', 'Property', 'verified', 'top 52%, left 59%', 'Ultra-exclusive gated island community featuring billionaire waterfront mansions, private boat docks, and exotic hypercar collections.', 'Gated Access (Armed Security)', 'Restricted Area', '/img/car-purple.jpg', 'CONFIRMED', 'Trailer 1 Luxury Villa Helicopter Sequence'),
  ('loc-via-airport', 'vice-city-international-airport', 'Vice City International Airport (VIA)', 'Airport / Western Vice', 'Airport / Helipad', 'verified', 'top 48%, left 48%', 'Massive civil aviation hub featuring commercial runways, private jet hangars, police helipads, and extreme stunt ramp launch points.', 'Open 24/7', 'Restricted Area', '/img/heli.jpg', 'CONFIRMED', 'Trailer 1 Plane Takeoff Background'),
  ('loc-ufo-mural', 'cryptic-ufo-radar-dome', 'Cryptic UFO Swamplands Mural', 'Grassrivers', 'Easter Egg', 'verified', 'top 32%, left 54%', 'Mysterious extraterrestrial artwork painted on an abandoned Cold War military radar installation. Emits strange audio frequencies during thunderstorms.', '00:00 – 04:00 (Rain/Thunderstorm only)', 'Low', '/img/ufo-mural.jpg', 'CONFIRMED', 'In-Game Leak Mystery Documentation'),
  ('loc-underground-garage', 'customs-garage-ocean-drive', 'Vice City Customs — Ocean Drive', 'Ocean Drive', 'Garage', 'verified', 'top 57%, left 63%', 'High-end vehicle modification garage offering widebody kits, engine dyno tuning, custom neon wraps, and instant resprays.', 'Open 24/7', 'Low', '/img/garage.jpg', 'OFFICIAL', 'Trailer 1 Lowrider & Tuner Car Meet'),
  ('loc-bayfront-penthouse', 'high-end-bayfront-penthouse', 'High-End Biscayne Bayfront Penthouse', 'Vice City Downtown', 'Property', 'verified', 'top 50%, left 60%', 'Luxury glass penthouse overlooking the Biscayne bay and neon skyline with private 10-car garage, helipad roof access, and security armory.', 'Private Residence', 'Low', '/img/apartment.jpg', 'CONFIRMED', 'Vice City High-Rise Leaks'),
  ('loc-northern-lookout', 'northern-wilds-fire-lookout', 'Northern Wilds Fire Lookout Peak', 'Northern Wilds', 'Point of Interest', 'verified', 'top 22%, left 34%', 'Elevated scenic vantage tower atop the state''s highest ridge offering 360-degree views across forests, logging trails, and distant city lights.', 'Open 24/7', 'Low', '/img/hero-dark.jpg', 'CONFIRMED', 'Wilderness Leaks & Map Topography'),
  ('loc-port-safehouse', 'port-gellhorn-underground-safehouse', 'Port Gellhorn Underground Safehouse', 'Port Gellhorn', 'Safehouse', 'verified', 'top 44%, left 33%', 'Reinforced industrial basement safehouse equipped with escape water tunnel to cargo docks, weapon modification bench, and vehicle stash.', 'Story Unlocked', 'Medium', '/img/garage.jpg', 'CONFIRMED', 'Story Mission Leak Documents'),
  ('loc-submerged-cache', 'submerged-biscayne-smuggler-cache', 'Submerged Reef Smuggler Cache', 'Biscayne Bay Reef', 'Collectible', 'verified', 'top 62%, left 67%', 'Waterproof steel cargo chest dropped onto coastal coral reef shelf during high-speed Coastguard chase. Requires scuba apparatus.', 'Requires Scuba Gear', 'Medium', '/img/cache-chest.jpg', 'CONFIRMED', 'Underwater Marine Assets')
