  ('prop-keys-marina-dock', 'leonida-keys-marina-slips', 'Leonida Keys Private Marina Slips', 'Leonida Keys', 'Marina Dock', 980000, '$980,000', 2, 8500, '$8,500 / hr ($204,000 / day)', '["4 Covered Deep-Water Boat Slips","Fuel Dock Pumps","Tackle & Bait Shop Front","Private Seaplane Mooring"]'::jsonb, '["High-Octane Marine Pumps","Night Navigation Beacons","Heavy Drydock Winch"]'::jsonb, '["Complete ''The Score: Bank of the Keys''"]'::jsonb, 'REPORTED', 'Maritime Real Estate Leaks', '/img/boat.jpg', NULL),
  ('prop-ocean-beach-motel', 'ocean-beach-starter-motel', 'Ocean Beach Safehouse Suite', 'Ocean Drive Waterfront', 'Safehouse', 0, 'FREE (Story Unlock)', 2, 0, 'None (Starting Safehouse)', '["Wardrobe & Outfit Changer","Weapon Storage Trunk","2-Car Curbside Parking","Sleep & Save Bed"]'::jsonb, '["Radio Stations Tuner","Wall Heist Planning Board"]'::jsonb, '["Prologue Story Progression"]'::jsonb, 'OFFICIAL', 'Trailer 1 Motel Room Shot', '/img/hero-dark.jpg', NULL)
INSERT INTO public.collectibles (id, slug, title, category, district, reward, requirements, description, guide_tip, coord_top, coord_left, confidence, source, img) VALUES
  ('col-pkg-01', 'hidden-package-ocean-view', 'Hidden Package #01: Ocean View Marina Pier', 'Hidden Packages', 'Ocean Beach', '$5,000 Cash + Combat Pistol Ammo Cache', 'None (Explore under the wooden boardwalk)', 'Waterproof wrapped contraband package wedged under the wooden pilings of South Beach marina pier.', 'Crouch under the eastern boardwalk at low tide or swim underneath to locate the blinking green LED beacon.', '58%', '65%', 'CONFIRMED', 'Verified Collectibles Manifest', '/img/crate.svg'),
  ('col-stunt-01', 'stunt-jump-airport-express', 'Stunt Jump #08: Airport Highway Ramp', 'Stunt Jumps', 'VIA Airport', '500 RP + Stunt Driver Achievement Progress', 'Fast sports car or motorbike (minimum 120 mph launch)', 'Billboard maintenance steel ramp launching over six lanes of highway traffic leading to the commercial airport terminal.', 'Line up your approach from 300 meters back on the service road. Land cleanly on four wheels without hitting street lamps.', '49%', '50%', 'CONFIRMED', 'Trailer 1 Stunt Geometry', '/img/car-orange.jpg'),
  ('col-radio-01', 'rebel-radio-antenna-wave103', 'Rebel Radio Station Transmitter #04', 'Rebel Radio', 'Downtown Vice City', 'Unlocks Wave 103 Underground Radio Track & $2,500', 'Climb maintenance ladder to rooftop transmission tower', 'Pirate radio frequency repeater unit clamped to the cellular antenna array atop the downtown bank building.', 'Take the external fire escape stairs to roof level. Cut the security padlock with bolt cutters to access the relay box.', '47%', '59%', 'CONFIRMED', 'In-Game Audio Asset References', '/img/hero-dark.jpg'),
  ('col-wildlife-01', 'wildlife-photo-pink-flamingo', 'Wildlife Photography: Rare Caribbean Flamingo', 'Wildlife Photos', 'Grassrivers Sanctuary', '$3,500 Cash + Audubon Nature Perk', 'Telephoto Camera Lens (Equip from weapon wheel)', 'Capture a close-up clear photograph of the rare bright-pink Caribbean Flamingo wading through the swamp reeds.', 'Crouch and approach against the wind so birds do not scatter. Capture photo while subject is centered in sunlight.', '37%', '53%', 'OFFICIAL', 'Trailer 1 Wildlife Showcase', '/img/flamingo.svg'),
  ('col-part-01', 'weapon-part-titanium-suppressor', 'Unique Weapon Part: Titanium Pistol Suppressor', 'Weapon Parts', 'Port Gellhorn Docks', 'Unlocks Free Suppressor Mount for all Handguns', 'Search inside open blue cargo container #714', 'Precision-milled aerospace-grade titanium suppressor prototype left behind in an abandoned smuggler crate.', 'Container is guarded by two cartel sentries. Eliminate them silently or enter via roof hatch at night.', '41%', '34%', 'CONFIRMED', 'Weapon Crafting Leak Data', '/img/gunstore.svg'),
  ('col-easter-01', 'easter-egg-ufo-dome-graffiti', 'Easter Egg: Mysterious Swampland Alien Mural', 'Easter Eggs', 'Grassrivers Marshlands', 'Cryptic Radio Signal + Alien Investigator Badge', 'Visit between 00:00 and 04:00 during heavy rain', 'Luminescent graffiti depicting a flying saucer hovering over the Everglades. Emits harmonic frequency on CB channel 9.', 'Set your in-game time or wait for an evening storm. The mural glows with green bioluminescent paint in pitch darkness.', '32%', '54%', 'CONFIRMED', 'Trailer 1 Mystery Teasers', '/img/ufo-mural.jpg')
INSERT INTO public.radio_stations (id, name, genre, host, frequency, accent_color, description, tracks, sort_order) VALUES
  ('wave-103', 'Wave 103', 'Synthwave / New Wave', 'Pamela Scott', '103.2 FM', '#B8AAFF', 'The neon heartbeat of Vice City, spinning nostalgic 80s synthesizers alongside modern darksynth and dreamwave.', '["Love Is a Long Road - Tom Petty","Blue Monday - New Order","Nightcall - Kavinsky","Voices Carry - ''Til Tuesday"]'::jsonb, 1),
  ('flash-fm', 'Flash FM', 'Pop & Top 40', 'Toni', '105.7 FM', '#F3A398', 'The freshest high-energy pop anthems blasting across the beachfront boulevard and high-rise clubs.', '["Billie Jean - Michael Jackson","Blinding Lights - The Weeknd","Self Control - Laura Branigan","Levitating - Dua Lipa"]'::jsonb, 2),
  ('fever-105', 'Fever 105', 'Funk, Soul & Disco', 'Oliver ''Ladykiller'' Biscuit', '105.1 FM', '#FBBF24', 'Groovy basslines and timeless soul rhythms designed to soundtrack sunset cruises down Ocean Drive.', '["And the Beat Goes On - The Whispers","Juicy Fruit - Mtume","Get Down On It - Kool & The Gang","Summer Madness - Kool & The Gang"]'::jsonb, 3),
  ('v-rock', 'V-Rock', 'Hard Rock & Metal', 'Lazlow', '98.3 FM', '#EF4444', 'High-octane guitar riffs, blazing solos, and roaring vocals for tear-assing down the highway.', '["You''ve Got Another Thing Comin'' - Judas Priest","Peace Sells - Megadeth","Bark at the Moon - Ozzy Osbourne","Cum On Feel the Noize - Quiet Riot"]'::jsonb, 4),
  ('radio-espantoso', 'Radio Espantoso', 'Latin Jazz & Salsa', 'Pepe', '92.8 FM', '#10B981', 'Authentic Latin rhythms, salsa dura, mambo, and Afro-Cuban percussion from the heart of Little Haiti and Little Havana.', '["La Murga - Héctor Lavoe & Willie Colón","Pedro Navaja - Rubén Blades","Oye Cómo Va - Tito Puente","El Cantante - Héctor Lavoe"]'::jsonb, 5)
